async function mapPool(items, concurrency, fn) {
  const results = new Array(items.length);
  let nextIndex = 0;

  async function worker() {
    while (true) {
      const i = nextIndex++;
      if (i >= items.length) return;
      results[i] = await fn(items[i], i);
    }
  }

  const workers = Array.from({ length: Math.min(concurrency, items.length) }, () => worker());
  await Promise.all(workers);
  return results;
}

const controller = new AbortController();
const ids = await redis.sMembers('pending:user-ids');

const profiles = await mapPool(ids, 10, async (id) => {
  const res = await fetch(`/api/users/${id}`, { signal: controller.signal });
  if (!res.ok) throw new Error(`user ${id}: ${res.status}`);
  return res.json();
});

await redis.set('profiles:batch', JSON.stringify(profiles));

function createSemaphore(max) {
  let active = 0;
  const queue = [];
  const acquire = () => new Promise((resolve) => {
    const tryAcquire = () => {
      if (active < max) { active++; resolve(() => { active--; queue.shift()?.(); }); }
      else queue.push(tryAcquire);
    };
    tryAcquire();
  });
  return { acquire };
}

